#!/usr/bin/env bash
# Generated by opsdir for ds-1 in env=prod,cloud=standby,ou=environments,dc=ciam-ops
# PingDS 7.5.1; joins the replication deployment of env=prod,cloud=source,ou=environments,dc=ciam-ops.
# Secrets are resolved at run time from references; no secret value is stored in this file.
# The TLS keystore (binding role ds-tls-keystore) is materialized by the secrets agent before this runs.
set -euo pipefail
DEPLOYMENT_ID="$(gcloud secrets versions access latest --secret='ds-deployment-id' --project='example-aero-ciam-standby')"
DEPLOYMENT_ID_PASSWORD="$(gcloud secrets versions access latest --secret='ds-deployment-password' --project='example-aero-ciam-standby')"
ROOT_PASSWORD="$(gcloud secrets versions access latest --secret='ds-root-password' --project='example-aero-ciam-standby')"

./setup \
  --serverId ds-1 \
  --deploymentId "$DEPLOYMENT_ID" \
  --deploymentIdPassword "$DEPLOYMENT_ID_PASSWORD" \
  --rootUserDn uid=admin \
  --rootUserPassword "$ROOT_PASSWORD" \
  --hostname ds-1.gcp.internal.example-aero.test \
  --adminConnectorPort 4444 \
  --ldapsPort 1636 \
  --httpsPort 8443 \
  --replicationPort 8989 \
  --bootstrapReplicationServer ds-1.gcp.internal.example-aero.test:8989 \
  --bootstrapReplicationServer ds-2.gcp.internal.example-aero.test:8989 \
  --bootstrapReplicationServer ds-1.aws.internal.example-aero.test:8989 \
  --bootstrapReplicationServer ds-2.aws.internal.example-aero.test:8989 \
  --bootstrapReplicationServer ds-3.aws.internal.example-aero.test:8989 \
  --profile ds-user-data \
  --set ds-user-data/baseDn:dc=partners,dc=example-aero,dc=test \
  --acceptLicense

